const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[],page=0,lastPlan=null,editOriginal=null;const pageSize=25;
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))||fallback}catch{return fallback}}
let overrides=readStore('lg-shipping-v1',{}),saved=readStore('lg-plans-v1',[]);
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{alert('Browser storage is unavailable or full. Export a backup to retain your data.');return false}}
function download(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function tab(name){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==name);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.tab===name));$('crumb').textContent={planner:'Pallet planner',chat:'Chat assistant',catalogue:'Product catalogue',saved:'Saved plans'}[name];if(name==='catalogue')renderCatalogue();if(name==='saved')renderSaved();}
document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>tab(e.dataset.tab));
function currentModel(){return products.find(p=>p.model.toUpperCase()===$('model').value.trim().toUpperCase())}
function ready(p){return p.dims?.length===3&&p.dims.every(v=>Number.isFinite(v)&&v>0)&&Number.isFinite(p.weight)&&p.weight>0}
function updateModel(){let p=currentModel();$('modelinfo').innerHTML=p?`${esc(p.name)}<br>${ready(p)?`Carton ${p.dims.join(' × ')} mm (W × D × H) · ${p.weight} kg gross`:'Shipping data incomplete · update in catalogue'} · ${p.userSupplied?'User supplied':`<a target="_blank" rel="noopener" href="${esc(p.url)}">LG source ↗</a>`}`:'Select an exact model from the catalogue.';}
$('model').oninput=updateModel;
function invalidate(){lastPlan=null;$('results').innerHTML='';$('visual').innerHTML='<div class="emptyicon">▧</div><h3>Your next load starts here</h3><p>Generate a plan to see carton placement,<br>pallet counts, and load utilization.</p>';$('error').textContent='';}
$('planform').addEventListener('input',invalidate);
function palletChange(){const custom=$('custom').checked,euro=document.querySelector('[name=pallet]:checked').value==='euro';$('length').disabled=$('depth').disabled=!custom;if(!custom){$('length').value=1200;$('depth').value=euro?800:1000}$('footprint').textContent=`${$('length').value} × ${$('depth').value} mm`;invalidate();}
$('custom').onchange=palletChange;document.querySelectorAll('[name=pallet]').forEach(e=>e.onchange=palletChange);
function settings(){let s={};for(const k of ['height','maxWeight','tare','palletHeight','layers'])s[k]=Number($(k).value);return {...s,L:Number($('length').value),D:Number($('depth').value),stackConfirmed:$('stackConfirmed').checked,type:$('custom').checked?'custom':document.querySelector('[name=pallet]:checked').value};}
$('planform').onsubmit=e=>{e.preventDefault();try{const p=currentModel();if(!p)throw Error('Select an exact model from the saved LG catalogue, or add its shipping data.');const s=settings();if(s.L>10000||s.D>10000)throw Error('Pallet dimensions must be 10,000 mm or less.');lastPlan=LoadPlanner.plan(p,Number($('quantity').value),s);lastPlan.source={url:p.url,checked:p.checked,userSupplied:!!p.userSupplied,note:p.note};renderPlan(lastPlan);}catch(err){$('error').textContent=err.message;}};
function renderPlan(plan){const s=plan.settings,n=plan.pallets.length,units=plan.pallets[0].units,footArea=plan.positions.slice(0,Math.min(plan.perLayer,units)).reduce((a,b)=>a+b.w*b.d,0),util=(100*footArea/(s.L*s.D)).toFixed(1);$('error').textContent='';$('footprint').textContent=`${s.L} × ${s.D} mm`;
 $('visual').innerHTML=`<svg role="img" aria-label="Top view of first pallet showing ${Math.min(plan.perLayer,units)} upright cartons" viewBox="-55 -55 ${s.L+110} ${s.D+110}"><rect x="0" y="0" width="${s.L}" height="${s.D}" fill="#e7ebdd" stroke="#b5c0a9" stroke-width="5"/>${plan.positions.slice(0,Math.min(plan.perLayer,units)).map((p,i)=>`<rect x="${p.x+3}" y="${p.y+3}" width="${Math.max(1,p.w-6)}" height="${Math.max(1,p.d-6)}" rx="8" fill="#a5be95" stroke="#69865c" stroke-width="3"/><text x="${p.x+p.w/2}" y="${p.y+p.d/2}" dominant-baseline="middle" text-anchor="middle" fill="#36522d" font-family="sans-serif" font-size="${Math.min(50,p.w/5,p.d/5)}">${i+1}</text>`).join('')}</svg>`;
 $('results').innerHTML=`<div class="stats"><div class="stat"><strong>${n}</strong><span>Pallets required</span></div><div class="stat"><strong>${plan.capacity}</strong><span>Cartons per full pallet</span></div><div class="stat"><strong>${util}%</strong><span>First-layer footprint use</span></div></div><div class="card resultcard"><h3>${esc(plan.model)} · ${plan.quantity} cartons</h3><div class="tablewrap"><table><thead><tr><th>PALLET</th><th>CARTONS</th><th>LAYERS</th><th>HEIGHT MM</th><th>GROSS KG</th></tr></thead><tbody>${plan.pallets.slice(0,100).map(p=>`<tr><td>${p.number}</td><td>${p.units}</td><td>${p.layers}</td><td>${p.height}</td><td>${p.grossWeight}</td></tr>`).join('')}</tbody></table></div>${n>100?'<p>First 100 pallets shown; export includes every pallet.</p>':''}<p>Total gross weight: <b>${plan.totalGrossWeight.toLocaleString()} kg</b> including pallet tare.<br>${esc(plan.method)} Final partial pallets use the same pattern, filled in sequence. Check carton support, restraint and handling instructions before loading.</p><div class="actions"><button class="secondary" id="saveplan">Save plan</button><button class="secondary" id="exportplan">Export JSON</button><button class="secondary" id="printplan">Print / PDF</button></div><p>Plan saves are local to this browser.</p></div>`;
 $('saveplan').onclick=()=>{const item={...plan,id:crypto.randomUUID(),created:new Date().toISOString()};const next=[item,...saved];if(persist('lg-plans-v1',next)){saved=next;$('saveplan').textContent='Saved ✓';$('saveplan').disabled=true;}};$('exportplan').onclick=()=>download(`${plan.model}-pallet-plan.json`,plan);$('printplan').onclick=()=>window.print();}
function renderCatalogue(){let q=$('search').value.trim().toLowerCase(),c=$('category').value,r=$('readiness').value,filtered=products.filter(p=>(!q||(p.model+' '+p.name).toLowerCase().includes(q))&&(!c||p.category===c)&&(!r||(r==='ready'?ready(p):!ready(p))));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/pageSize)-1));const start=page*pageSize;
 $('productsbody').innerHTML=filtered.slice(start,start+pageSize).map(p=>`<tr><td><strong>${esc(p.model)}</strong><small>${esc(p.name)}</small>${p.url?`<a class="textbtn" href="${esc(p.url)}" target="_blank" rel="noopener">LG source ↗</a>`:''}</td><td>${esc(p.category.replaceAll('-',' '))}</td><td>${p.dims?.[0]??'—'}</td><td>${p.dims?.[1]??'—'}</td><td>${p.dims?.[2]??'—'}</td><td>${p.weight??'—'}</td><td><span class="status ${ready(p)?'':'missing'}">${p.userSupplied?'User supplied':ready(p)?'LG shipping data':'Needs shipping data'}</span></td><td><button class="textbtn" data-dimensions="${esc(p.model)}">All dimensions</button><br><button class="textbtn" data-edit="${esc(p.model)}">Edit</button> <button class="textbtn" data-use="${esc(p.model)}">Plan</button></td></tr>`).join('')||'<tr><td colspan="8">No matching models. Add a model with verified shipping data.</td></tr>';
 $('rowcount').textContent=`${filtered.length?start+1:0}–${Math.min(start+pageSize,filtered.length)} of ${filtered.length} models`;$('prev').disabled=!page;$('next').disabled=start+pageSize>=filtered.length;
 document.querySelectorAll('[data-dimensions]').forEach(b=>b.onclick=()=>showDimensions(products.find(p=>p.model===b.dataset.dimensions)));
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(products.find(p=>p.model===b.dataset.edit)));document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>{$('model').value=b.dataset.use;invalidate();updateModel();tab('planner');});}
for(const k of ['search','category','readiness'])$(k).addEventListener(k==='search'?'input':'change',()=>{page=0;renderCatalogue()});$('prev').onclick=()=>{page--;renderCatalogue()};$('next').onclick=()=>{page++;renderCatalogue()};
function refreshProducts(){products.sort((a,b)=>a.model.localeCompare(b.model));$('navcount').textContent=products.length;$('models').innerHTML=products.map(p=>`<option value="${esc(p.model)}">${esc(p.name)}</option>`).join('');let c=$('category').value;$('category').innerHTML='<option value="">All categories</option>'+[...new Set(products.map(p=>p.category))].sort().map(c=>`<option value="${esc(c)}">${esc(c.replaceAll('-',' '))}</option>`).join('');$('category').value=c;updateModel();renderCatalogue();}
function edit(p){editOriginal=p?.model||null;$('emodel').value=p?.model||'';$('emodel').readOnly=!!p;$('ename').value=p?.name||'';['ew','ed','eh'].forEach((k,i)=>$(k).value=p?.dims?.[i]||'');$('eweight').value=p?.weight||'';$('esource').value=p?.note||p?.url||'';$('editor').showModal()}
$('addproduct').onclick=()=>edit(null);$('closeeditor').onclick=()=>$('editor').close();$('editform').onsubmit=e=>{e.preventDefault();let model=$('emodel').value.trim().toUpperCase();if(!editOriginal&&products.some(p=>p.model.toUpperCase()===model)){alert('This model exists. Edit its existing record.');return;}const old=products.find(p=>p.model===editOriginal);let p={...old,model,name:$('ename').value.trim(),category:old?.category||'user-added',dims:['ew','ed','eh'].map(k=>Number($(k).value)),weight:Number($('eweight').value),note:$('esource').value.trim(),userSupplied:true,checked:new Date().toISOString().slice(0,10),market:'Saudi Arabia'};if(!ready(p)){alert('Enter valid positive dimensions and weight.');return;}if(!persist('lg-shipping-v1',{...overrides,[model]:p}))return;overrides[model]=p;products=products.filter(x=>x.model!==model).concat(p);refreshProducts();invalidate();$('editor').close();};
$('exportcatalogue').onclick=()=>download('lg-saudi-catalogue.json',products);
$('importfile').onchange=async e=>{try{let incoming=JSON.parse(await e.target.files[0].text());if(!Array.isArray(incoming)||incoming.length>10000)throw Error('Expected an array of up to 10,000 product records.');let next={...overrides};for(let p of incoming){if(typeof p.model!=='string'||!p.model.trim()||typeof p.name!=='string')throw Error('Each record needs a model and name.');if(!ready(p))throw Error(`Missing or invalid shipping dimensions/weight for ${p.model}. Import only completed records.`);let url=typeof p.url==='string'&&/^https:\/\/www\.lg\.com\//.test(p.url)?p.url:undefined;next[p.model.toUpperCase()]={model:p.model.toUpperCase(),name:p.name,category:typeof p.category==='string'?p.category:'user-added',dims:p.dims,weight:p.weight,url,note:String(p.note||'Imported by user'),userSupplied:true,market:'Saudi Arabia',checked:new Date().toISOString().slice(0,10)};}if(persist('lg-shipping-v1',next)){overrides=next;let map=new Map(products.map(p=>[p.model,p]));Object.values(next).forEach(p=>map.set(p.model,p));products=[...map.values()];refreshProducts();invalidate();}}catch(err){alert('Import failed: '+err.message)}e.target.value='';};
function renderSaved(){$('savedlist').innerHTML=saved.map((p,i)=>`<div class="card savedcard"><div><h3>${esc(p.model)} · ${p.quantity} cartons</h3><p>${p.pallets.length} pallets · ${p.settings.L} × ${p.settings.D} mm · ${esc(new Date(p.created).toLocaleDateString())}</p></div><div class="actions"><button class="secondary" data-open="${i}">View</button><button class="secondary" data-download="${i}">Export</button><button class="textbtn" data-delete="${i}">Delete</button></div></div>`).join('')||'<div class="card resultcard"><h3>No plans saved yet</h3><p>Generate a pallet plan, then select Save plan.</p></div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let p=saved[Number(b.dataset.open)];$('model').value=p.model;$('quantity').value=p.quantity;$('custom').checked=p.settings.type==='custom';document.querySelector(`[name=pallet][value="${p.settings.type==='euro'?'euro':'standard'}"]`).checked=true;palletChange();$('length').value=p.settings.L;$('depth').value=p.settings.D;for(const k of ['height','maxWeight','tare','palletHeight','layers'])$(k).value=p.settings[k];$('stackConfirmed').checked=p.settings.stackConfirmed;updateModel();lastPlan=p;renderPlan(p);tab('planner');});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download('pallet-plan.json',saved[Number(b.dataset.download)]));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const next=saved.filter((_,i)=>i!==Number(b.dataset.delete));if(persist('lg-plans-v1',next)){saved=next;renderSaved()}});}
Promise.all([fetch('products.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()}),fetch('import-report.json').then(r=>r.json())]).then(([data,report])=>{let map=new Map(data.map(p=>[p.model,p]));Object.values(overrides).forEach(p=>{const source=map.get(p.model);map.set(p.model,{...source,...p,dimensionSpecs:source?.dimensionSpecs||p.dimensionSpecs,unitNote:source?.unitNote||p.unitNote});});products=[...map.values()];refreshProducts();$('coverage').textContent=`${data.length.toLocaleString()} model listings · LG Saudi Arabia · checked ${report.checked}`;$('report').textContent=`${data.length} Saudi sitemap model listings checked. ${report.withDimensionSpecs??report.ready} have published dimension/weight specifications; ${report.withDimensions??report.ready} have carton dimensions; ${report.ready} have both carton dimensions and gross weight for planning. ${report.errors.length} pages could not be verified. Missing values remain blank. Use All dimensions to view the original LG specifications and axis order. Listings may include discontinued models; completeness and current availability are not guaranteed.`;}).catch(err=>{$('error').textContent='Catalogue could not load. Reload the page. '+err.message;$('coverage').textContent='Catalogue failed to load.'});

function showDimensions(p){
 $('dimensiontitle').textContent=p.model+' · Dimensions & weights';
 $('dimensionsource').innerHTML=`${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener">LG Saudi Arabia source ↗</a>`:''} · Checked ${esc(p.checked||'unknown')}${p.userSupplied?' · Planner shipping data edited by user':''}`;
 let rows=[];
 if(p.dims) rows.push({label:'Planner carton W × D × H (mm)',value:p.dims.join(' × ')});
 if(p.weight) rows.push({label:'Planner gross carton weight (kg)',value:p.weight});
 rows.push(...(p.dimensionSpecs||[]));
 $('dimensionrows').innerHTML=rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.value)}</td></tr>`).join('')||'<tr><td colspan="2">LG specifications are unavailable for this listing. Add verified shipping data using Edit.</td></tr>';
 if(p.unitNote)$('dimensionsource').innerHTML+=`<br>${esc(p.unitNote)}`;
 $('dimensionsdialog').showModal();
}
$('closedimensions').onclick=()=>$('dimensionsdialog').close();
